using InventorySystem.Domain.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace InventorySystem.Infrastructure.EntityConfigurations; public sealed class PersonnelConfiguration:IEntityTypeConfiguration<Personnel>{public void Configure(EntityTypeBuilder<Personnel>b){b.ToTable("Personnel");b.HasKey(p=>p.Id);b.Property(p=>p.SicilNo).HasMaxLength(50).IsRequired();b.Property(p=>p.Ad).HasMaxLength(100).IsRequired();b.Property(p=>p.Soyad).HasMaxLength(100).IsRequired();b.Property(p=>p.Departman).HasMaxLength(120).IsRequired();b.Property(p=>p.Pozisyon).HasMaxLength(120).IsRequired();b.Property(p=>p.Eposta).HasMaxLength(200);b.Property(p=>p.ZimmetNo).HasMaxLength(50);b.HasIndex(p=>p.SicilNo).IsUnique().HasFilter("\"IsDeleted\" = false");b.HasIndex(p=>p.ZimmetNo);b.HasQueryFilter(p=>!p.IsDeleted);}}
